interpretations.sql:
SELECT store_id, sqm AS metric_value FROM dim_store WHERE is_current AND store_id < 900 AND close_date IS NULL
ORDER BY 2 DESC, 1
LIMIT 10;

naive.sql:
SELECT 25.5 AS vat_rate_pct, ROUND(SUM(f.net_amount) * 0.255, 2) AS vat_amount
FROM fact_sales_line f JOIN dim_store s ON s.store_key = f.store_key JOIN dim_product p ON p.product_key = f.product_key
WHERE s.store_id < 900 AND p.category <> 'ZZ Test' AND f.sale_date BETWEEN DATE '2024-08-26' AND DATE '2024-09-22';

reference.sql:
SELECT SUM(f.quantity) AS units_sold
FROM fact_sales_line f JOIN dim_store s ON s.store_key = f.store_key JOIN dim_product p ON p.product_key = f.product_key
WHERE s.store_id = 131 AND p.sku = 101624 AND f.sale_date BETWEEN DATE '2026-09-28' AND DATE '2026-10-04';

interpretations.sql:
SELECT COUNT(DISTINCT m.member_id) AS customers
FROM fact_sales_line f JOIN dim_store s ON s.store_key = f.store_key JOIN dim_member m ON m.member_key = f.member_key
WHERE s.store_id IN (SELECT store_id FROM dim_store WHERE city = 'Tampere' AND store_id < 900 AND is_current) AND f.sale_date > DATE '2026-10-04' - 364 AND f.sale_date <= DATE '2026-10-04';

reference.sql:
SELECT ROUND(AVG(weekly), 2) AS average_stock_value FROM (SELECT w.week_ending_date, SUM(w.closing_value) AS weekly FROM fact_stock_week w JOIN dim_product p ON p.product_key = w.product_key JOIN dim_product cp ON cp.sku = p.sku AND cp.is_current
JOIN dim_date d ON d.calendar_date = w.week_ending_date
WHERE cp.category = 'Paint & Decorating' AND d.fiscal_year = 'FY2026/27' AND d.fiscal_period = 3 GROUP BY 1);

naive.sql:
SELECT ROUND(SUM(w.closing_value), 2) AS average_stock_value FROM fact_stock_week w JOIN dim_product p ON p.product_key = w.product_key JOIN dim_product cp ON cp.sku = p.sku AND cp.is_current
JOIN dim_date d ON d.calendar_date = w.week_ending_date
WHERE cp.category = 'Paint & Decorating' AND d.fiscal_year = 'FY2026/27' AND d.fiscal_period = 3;

SELECT ROUND(AVG(w.closing_value), 2) AS average_stock_value FROM fact_stock_week w JOIN dim_product p ON p.product_key = w.product_key JOIN dim_product cp ON cp.sku = p.sku AND cp.is_current
JOIN dim_date d ON d.calendar_date = w.week_ending_date
WHERE cp.category = 'Paint & Decorating' AND d.fiscal_year = 'FY2026/27' AND d.fiscal_period = 3;
